-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
hl.config({
	general = {
		gaps_in = 5,
		gaps_out = 20, -- Halloween: more room around windows, same as the hyprlang config

		border_size = 2,

		col = {
			active_border = { colors = { "rgba(33ccffee)", "rgba(00ff99ee)" }, angle = 45 },
			inactive_border = "rgba(595959aa)",
		},

		-- Set to true to enable resizing windows by clicking and dragging on borders and gaps
		resize_on_border = true,

		-- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
		allow_tearing = false,

		layout = "dwindle",
	},

	decoration = {
		rounding = 6,
		rounding_power = 2,

		-- Ghostly windows: focused stays readable, unfocused falls back into the blur
		active_opacity = 0.5,
		inactive_opacity = 0.3,

		shadow = {
			enabled = true,
			range = 4,
			render_power = 3,
			-- rgba(1a1a1aee) in legacy ARGB. Same value as the hyprlang Halloween shadow.
			color = 0xee1a1a1a,
		},

		-- Heavier kawase blur so the wallpaper shows through the transparent windows.
		-- popups is left at the wiki default (false); the hyprlang file does not set it.
		blur = {
			enabled = true,
			size = 5,
			passes = 5,
			vibrancy = 0.1696,
		},
	},

	animations = {
		enabled = true,
	},
})

-- Halloween motion. See https://wiki.hypr.land/Configuring/Advanced-and-Cool/Animations/
-- Cubic beziers take the two middle control points. Speed is in deciseconds (1 = 100ms).
-- Leaves that are not set here inherit `global`, which is what the hyprlang file relies on.

-- Slow smooth easing for ghostly moves
hl.curve("spookySlow", { type = "bezier", points = { { 0.1, 0.8 }, { 0.2, 0.9 } } })
-- Quick, jittery curve for exits
hl.curve("quickJitter", { type = "bezier", points = { { 0.6, 0.1 }, { 0.4, 0.9 } } })
-- Soft fade with a dip in the middle
hl.curve("creepFade", { type = "bezier", points = { { 0.3, 0 }, { 0.7, 0.15 } } })

-- Slow base timing. Unset leaves (windowsMove, fadeSwitch, borderangle, zoomFactor, …) inherit this.
hl.animation({ leaf = "global", enabled = true, speed = 12, bezier = "spookySlow" })
hl.animation({ leaf = "border", enabled = true, speed = 6, bezier = "spookySlow" })

-- Windows pop in like ghosts, then jitter on the way out
hl.animation({ leaf = "windows", enabled = true, speed = 5, bezier = "spookySlow" })
hl.animation({ leaf = "windowsIn", enabled = true, speed = 6, bezier = "spookySlow", style = "popin 75%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 3, bezier = "quickJitter", style = "popin 75%" })

-- Fade in/out with the dipped curve
hl.animation({ leaf = "fadeIn", enabled = true, speed = 2.5, bezier = "creepFade" })
hl.animation({ leaf = "fadeOut", enabled = true, speed = 2.5, bezier = "creepFade" })
hl.animation({ leaf = "fade", enabled = true, speed = 3.5, bezier = "quickJitter" })

hl.animation({ leaf = "layers", enabled = true, speed = 4.5, bezier = "spookySlow" })
hl.animation({ leaf = "layersIn", enabled = true, speed = 5, bezier = "spookySlow", style = "fade" })
hl.animation({ leaf = "layersOut", enabled = true, speed = 2, bezier = "quickJitter", style = "fade" })

hl.animation({ leaf = "fadeLayersIn", enabled = true, speed = 2.5, bezier = "creepFade" })
hl.animation({ leaf = "fadeLayersOut", enabled = true, speed = 2.5, bezier = "creepFade" })

-- Workspace changes fade instead of sliding
hl.animation({ leaf = "workspaces", enabled = true, speed = 2.5, bezier = "creepFade", style = "fade" })
hl.animation({ leaf = "workspacesIn", enabled = true, speed = 1.8, bezier = "creepFade", style = "fade" })
hl.animation({ leaf = "workspacesOut", enabled = true, speed = 2.5, bezier = "creepFade", style = "fade" })

